public sealed record WebhookPayload(string Url, string Body);

public interface IRetryPolicy
{
    Task<T> ExecuteAsync<T>(Func<CancellationToken, Task<T>> action, CancellationToken ct);
}

public sealed class SimpleRetryPolicy : IRetryPolicy
{
    private readonly int _maxAttempts;
    public SimpleRetryPolicy(int maxAttempts = 3) => _maxAttempts = maxAttempts;

    public async Task<T> ExecuteAsync<T>(Func<CancellationToken, Task<T>> action, CancellationToken ct)
    {
        for (var attempt = 1; ; attempt++)
        {
            try { return await action(ct).ConfigureAwait(false); }
            catch (OperationCanceledException) { throw; }
            catch (Exception) when (attempt < _maxAttempts)
            {
                await Task.Delay(TimeSpan.FromMilliseconds(50 * attempt), ct).ConfigureAwait(false);
            }
        }
    }
}

public interface IWebhookDispatcher
{
    ValueTask EnqueueAsync(WebhookPayload payload, CancellationToken ct);
}

public sealed class WebhookDispatcher : IWebhookDispatcher, IAsyncDisposable
{
    private readonly HttpClient _http;
    private readonly IRetryPolicy _retry;
    private readonly Action<WebhookPayload, Exception> _onFailed;
    private readonly SemaphoreSlim _concurrency;
    private readonly Channel<WebhookPayload> _queue;
    private readonly CancellationTokenSource _cts = new();
    private readonly Task _pump;

    public WebhookDispatcher(
        HttpClient http,
        IRetryPolicy retry,
        Action<WebhookPayload, Exception> onFailed,
        int queueCapacity,
        int maxConcurrency)
    {
        _http = http;
        _retry = retry;
        _onFailed = onFailed;
        _concurrency = new SemaphoreSlim(maxConcurrency, maxConcurrency);
        _queue = Channel.CreateBounded<WebhookPayload>(new BoundedChannelOptions(queueCapacity)
        {
            FullMode = BoundedChannelFullMode.Wait,
        });
        _pump = Task.Run(() => PumpAsync(_cts.Token));
    }

    public ValueTask EnqueueAsync(WebhookPayload payload, CancellationToken ct) =>
        _queue.Writer.WriteAsync(payload, ct);

    private async Task PumpAsync(CancellationToken ct)
    {
        var inFlight = new List<Task>();
        try
        {
            await foreach (var item in _queue.Reader.ReadAllAsync(ct).ConfigureAwait(false))
            {
                await _concurrency.WaitAsync(ct).ConfigureAwait(false);
                inFlight.RemoveAll(t => t.IsCompleted);
                inFlight.Add(DeliverWithReleaseAsync(item, ct));
            }
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
        }
        await Task.WhenAll(inFlight).ConfigureAwait(false);
    }

    private async Task DeliverWithReleaseAsync(WebhookPayload item, CancellationToken ct)
    {
        try
        {
            await _retry.ExecuteAsync(async token =>
            {
                using var content = new StringContent(item.Body);
                using var resp = await _http.PostAsync(item.Url, content, token).ConfigureAwait(false);
                resp.EnsureSuccessStatusCode();
                return true;
            }, ct).ConfigureAwait(false);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
        }
        catch (Exception ex)
        {
            _onFailed(item, ex);
        }
        finally
        {
            _concurrency.Release();
        }
    }

    public async ValueTask DisposeAsync()
    {
        _queue.Writer.TryComplete();
        _cts.Cancel();
        await _pump.ConfigureAwait(false);
        _cts.Dispose();
        _concurrency.Dispose();
    }
}
